  CONSTRAINT `cajas_cajero_asignado_id_foreign` FOREIGN KEY (`cajero_asignado_id`) REFERENCES `users` (`id`),
  CONSTRAINT `cajas_ubicacion_id_foreign` FOREIGN KEY (`ubicacion_id`) REFERENCES `ubicaciones` (`id`)
