  `variante_producto_id` bigint(20) unsigned DEFAULT NULL,
  `cantidad` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `items_traslado_stock_traslado_stock_id_foreign` (`traslado_stock_id`),
  KEY `items_traslado_stock_producto_id_foreign` (`producto_id`),
  KEY `items_traslado_stock_variante_producto_id_foreign` (`variante_producto_id`),
  CONSTRAINT `items_traslado_stock_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `items_traslado_stock_traslado_stock_id_foreign` FOREIGN KEY (`traslado_stock_id`) REFERENCES `traslados_stock` (`id`) ON DELETE CASCADE,
  CONSTRAINT `items_traslado_stock_variante_producto_id_foreign` FOREIGN KEY (`variante_producto_id`) REFERENCES `variantes_productos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9923 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
