DROP TABLE IF EXISTS `log_traslados`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `log_traslados` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `traslado_stock_id` bigint(20) unsigned NOT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `accion` varchar(50) NOT NULL,
  `detalle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`detalle`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `log_traslados_traslado_stock_id_foreign` (`traslado_stock_id`),
  KEY `log_traslados_usuario_id_foreign` (`usuario_id`),
  CONSTRAINT `log_traslados_traslado_stock_id_foreign` FOREIGN KEY (`traslado_stock_id`) REFERENCES `traslados_stock` (`id`) ON DELETE CASCADE,
  CONSTRAINT `log_traslados_usuario_id_foreign` FOREIGN KEY (`usuario_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

