--
-- Table structure for table `novedades_stock`
--

DROP TABLE IF EXISTS `novedades_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `novedades_stock` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `producto_id` bigint(20) unsigned NOT NULL,
  `variante_producto_id` bigint(20) unsigned DEFAULT NULL,
  `ubicacion_id` bigint(20) unsigned NOT NULL,
  `tipo` enum('garantia','saldo','perdida','dano') NOT NULL,
  `cantidad` int(11) NOT NULL,
  `valor_original` decimal(12,2) NOT NULL,
  `valor_saldo` decimal(12,2) DEFAULT NULL,
  `descripcion` text NOT NULL,
  `estado` enum('pendiente','procesado','recuperado','dado_de_baja') NOT NULL DEFAULT 'pendiente',
  `numero_garantia` varchar(255) DEFAULT NULL,
  `fecha_vencimiento_garantia` date DEFAULT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `usuario_cierre_id` bigint(20) unsigned DEFAULT NULL,
  `cerrado_en` timestamp NULL DEFAULT NULL,
  `notas_cierre` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `novedades_stock_producto_id_foreign` (`producto_id`),
  KEY `novedades_stock_variante_producto_id_foreign` (`variante_producto_id`),
  KEY `novedades_stock_ubicacion_id_foreign` (`ubicacion_id`),
  KEY `novedades_stock_usuario_id_foreign` (`usuario_id`),
  KEY `novedades_stock_usuario_cierre_id_foreign` (`usuario_cierre_id`),
  CONSTRAINT `novedades_stock_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `novedades_stock_ubicacion_id_foreign` FOREIGN KEY (`ubicacion_id`) REFERENCES `ubicaciones` (`id`),
  CONSTRAINT `novedades_stock_usuario_cierre_id_foreign` FOREIGN KEY (`usuario_cierre_id`) REFERENCES `users` (`id`),
  CONSTRAINT `novedades_stock_usuario_id_foreign` FOREIGN KEY (`usuario_id`) REFERENCES `users` (`id`),
  CONSTRAINT `novedades_stock_variante_producto_id_foreign` FOREIGN KEY (`variante_producto_id`) REFERENCES `variantes_productos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
