INSERT INTO `productos` VALUES (218,'1001','Esmalte semipermanente x 15ml','Explora un universo de color con nuestros esmaltes semipermanentes de 15ml. Elige entre 70 tonos vibrantes de alta pigmentación para crear manicuras perfectas y de larga duración. ¡Cambia de color tan a menudo como quieras, sin sacrificar la calidad ni la intensidad!',NULL,NULL,'Unidad','Unidad',NULL,10,1,0,1,1,0,'2026-02-12 13:35:05','2026-04-23 23:29:53'),(219,'1004-A','Pegante en gel x 15 ml','Adhesivo profesional para uñas. Fijación fuerte y duradera para tips y decoraciones. ¡Resultados impecables y seguros!',NULL,NULL,'Unidad','Unidad',NULL,10,1,0,0,1,0,'2026-02-12 14:31:22','2026-02-12 14:31:22'),(221,'1002','Ultrabond x 15 ml','Primer sin ácido para máxima adherencia en uñas acrílicas y de gel. Previene levantamientos. ¡Durabilidad y cero desprendimientos!',NULL,NULL,'Unidad','Unidad',NULL,10,1,0,0,1,0,'2026-02-12 14:36:12','2026-02-12 14:36:12'),(222,'1004-B','Base rubber color x 15 ml','Base flexible para fortalecer uñas débiles. Nivela imperfecciones y protege el crecimiento. ¡Uñas más resistentes y sanas!',NULL,NULL,'Unidad','Unidad',NULL,10,1,0,1,1,0,'2026-02-12 15:17:57','2026-02-12 15:17:57'),(223,'1265','Painting Gel Efecto Espejo - 8 ml','Gel de alta pigmentación para acabados metálicos. Crea diseños con efecto espejo en tus uñas. ¡Brillo impactante y moderno!',NULL,NULL,'Unidad','Unidad',NULL,11,1,0,0,1,0,'2026-02-12 15:24:38','2026-02-12 15:24:38'),(224,'1266','Painting Gel de Saturación Individual - 8ml','Gel de alta pigmentación para nail art. Color intenso y cobertura total. ¡Crea diseños precisos y vibrantes en tus uñas!',NULL,NULL,'Unidad','Unidad',NULL,11,1,0,1,1,0,'2026-02-12 15:26:52','2026-02-12 15:26:52'),(225,'1267','Spider Gel - 8ml','Gel elástico para nail art. Crea líneas finas y diseños geométricos únicos. ¡Textura y creatividad en tus uñas!',NULL,NULL,'Unidad','Unidad',NULL,11,1,0,1,1,0,'2026-02-12 15:37:21','2026-02-12 15:37:21'),(226,'1274','Lámpara de Me