--
-- Table structure for table `reservas_stock`
--

DROP TABLE IF EXISTS `reservas_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reservas_stock` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `solicitud_cotizacion_id` bigint(20) unsigned NOT NULL,
  `item_solicitud_id` bigint(20) unsigned NOT NULL,
  `stock_producto_id` bigint(20) unsigned NOT NULL,
  `cantidad_reservada` int(11) NOT NULL,
  `expira_en` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `liberada_en` timestamp NULL DEFAULT NULL,
  `estado` enum('activa','aplicada','expirada','liberada_manual') NOT NULL DEFAULT 'activa',
  `motivo_liberacion` varchar(255) DEFAULT NULL,
  `liberada_por` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reservas_stock_item_solicitud_id_foreign` (`item_solicitud_id`),
  KEY `reservas_stock_liberada_por_foreign` (`liberada_por`),
  KEY `reservas_stock_estado_expira_en_index` (`estado`,`expira_en`),
  KEY `reservas_stock_solicitud_cotizacion_id_index` (`solicitud_cotizacion_id`),
  KEY `reservas_stock_stock_producto_id_index` (`stock_producto_id`),
  CONSTRAINT `reservas_stock_item_solicitud_id_foreign` FOREIGN KEY (`item_solicitud_id`) REFERENCES `items_solicitud_cotizacion` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reservas_stock_liberada_por_foreign` FOREIGN KEY (`liberada_por`) REFERENCES `users` (`id`),
  CONSTRAINT `reservas_stock_solicitud_cotizacion_id_foreign` FOREIGN KEY (`solicitud_cotizacion_id`) REFERENCES `solicitudes_cotizacion` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reservas_stock_stock_producto_id_foreign` FOREIGN KEY (`stock_producto_id`) REFERENCES `stock_productos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45336 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

