--
-- Table structure for table `solicitudes_cotizacion`
--

DROP TABLE IF EXISTS `solicitudes_cotizacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `solicitudes_cotizacion` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `numero_solicitud` varchar(255) NOT NULL,
  `cliente_id` bigint(20) unsigned NOT NULL,
  `sucursal_id` bigint(20) unsigned DEFAULT NULL,
  `enlace_acceso_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `estado` enum('pendiente','aplicada','rechazada') DEFAULT 'pendiente',
  `estado_pago` enum('pendiente','parcial','pagado') NOT NULL DEFAULT 'pendiente',
  `estado_envio` enum('pendiente','preparando','despachado','en_transito','entregado') NOT NULL DEFAULT 'pendiente',
  `numero_guia` varchar(100) DEFAULT NULL,
  `transportadora` varchar(100) DEFAULT NULL,
  `archivo_guia` varchar(255) DEFAULT NULL,
  `despachado_en` timestamp NULL DEFAULT NULL,
  `despachado_por` bigint(20) unsigned DEFAULT NULL,
  `entregado_en` timestamp NULL DEFAULT NULL,
  `metodo_pago` enum('transferencia','efectivo','credito','tarjeta','cheque','otro') DEFAULT NULL,
  `comprobante_pago` varchar(255) DEFAULT NULL,
  `monto_pagado` decimal(12,2) NOT NULL DEFAULT 0.00,
  `monto_credito` decimal(12,2) DEFAULT NULL,
  `pagado_en` timestamp NULL DEFAULT NULL,
  `verificado_por` bigint(20) unsigned DEFAULT NULL,
  `verificado_en` timestamp NULL DEFAULT NULL,
  `notas_pago` text DEFAULT NULL,
  `numero_factura` varchar(255) DEFAULT NULL,
  `facturada_en` timestamp NULL DEFAULT NULL,
  `facturada_por` bigint(20) unsigned DEFAULT NULL,
  `archivo_factura` varchar(255) DEFAULT NULL,
  `porcentaje_iva` decimal(5,2) DEFAULT NULL,
  `valor_iva` decimal(12,2) DEFAULT NULL,
  `forma_pago_factura` varchar(50) DEFAULT NULL,
  `fecha_vencimiento` date DEFAULT NULL,
  `monto_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `valor_flete` decimal(10,2) DEFAULT 0.00,
  `descuento_total` decimal(10,2) DEFAULT 0.00,
