--
-- Table structure for table `traslados_stock`
--

DROP TABLE IF EXISTS `traslados_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `traslados_stock` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `numero_traslado` varchar(255) NOT NULL,
  `ubicacion_origen_id` bigint(20) unsigned NOT NULL,
  `ubicacion_destino_id` bigint(20) unsigned NOT NULL,
  `estado` enum('pendiente','en_transito','completado','cancelado') NOT NULL DEFAULT 'pendiente',
  `notas` text DEFAULT NULL,
  `observacion_recepcion` text DEFAULT NULL,
  `tipo_operacion` enum('general','credito') NOT NULL DEFAULT 'general',
  `usuario_creador_id` bigint(20) unsigned NOT NULL,
  `usuario_receptor_id` bigint(20) unsigned DEFAULT NULL,
  `enviado_en` timestamp NULL DEFAULT NULL,
  `recibido_en` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `traslados_stock_numero_traslado_unique` (`numero_traslado`),
  KEY `traslados_stock_ubicacion_origen_id_foreign` (`ubicacion_origen_id`),
  KEY `traslados_stock_ubicacion_destino_id_foreign` (`ubicacion_destino_id`),
  KEY `traslados_stock_usuario_creador_id_foreign` (`usuario_creador_id`),
  KEY `traslados_stock_usuario_receptor_id_foreign` (`usuario_receptor_id`),
  CONSTRAINT `traslados_stock_ubicacion_destino_id_foreign` FOREIGN KEY (`ubicacion_destino_id`) REFERENCES `ubicaciones` (`id`),
  CONSTRAINT `traslados_stock_ubicacion_origen_id_foreign` FOREIGN KEY (`ubicacion_origen_id`) REFERENCES `ubicaciones` (`id`),
  CONSTRAINT `traslados_stock_usuario_creador_id_foreign` FOREIGN KEY (`usuario_creador_id`) REFERENCES `users` (`id`),
  CONSTRAINT `traslados_stock_usuario_receptor_id_foreign` FOREIGN KEY (`usuario_receptor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

