--
-- Table structure for table `ventas_pdv`
--

DROP TABLE IF EXISTS `ventas_pdv`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ventas_pdv` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sesion_caja_id` bigint(20) unsigned DEFAULT NULL,
  `caja_id` bigint(20) unsigned DEFAULT NULL,
  `prefactura_id` bigint(20) unsigned DEFAULT NULL,
  `numero_venta` varchar(255) NOT NULL,
  `ubicacion_id` bigint(20) unsigned NOT NULL,
  `cliente_id` bigint(20) unsigned DEFAULT NULL,
  `nombre_cliente` varchar(255) DEFAULT NULL,
  `lista_precio_id` bigint(20) unsigned DEFAULT NULL,
  `subtotal` decimal(12,2) NOT NULL,
  `descuento_global` decimal(10,2) NOT NULL DEFAULT 0.00,
  `descuento` decimal(10,2) NOT NULL DEFAULT 0.00,
  `iva` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(12,2) NOT NULL,
  `total_devoluciones` decimal(12,2) NOT NULL DEFAULT 0.00,
  `metodo_pago` enum('efectivo','tarjeta','transferencia','mixto') NOT NULL DEFAULT 'efectivo',
  `monto_efectivo` decimal(12,2) DEFAULT NULL,
  `monto_tarjeta` decimal(12,2) DEFAULT NULL,
  `monto_transferencia` decimal(12,2) DEFAULT NULL,
  `monto_recibido` decimal(12,2) DEFAULT NULL,
  `cambio` decimal(12,2) DEFAULT NULL,
  `tipo_transferencia` varchar(255) DEFAULT NULL,
  `comprobante_pago` varchar(255) DEFAULT NULL,
  `estado` enum('completada','anulada') NOT NULL DEFAULT 'completada',
  `factura_siigo_id` bigint(20) unsigned DEFAULT NULL,
  `requiere_factura` tinyint(1) NOT NULL DEFAULT 0,
  `notas` text DEFAULT NULL,
  `usuario_id` bigint(20) unsigned NOT NULL,
  `descuento_autorizado_por` bigint(20) unsigned DEFAULT NULL,
  `precio_autorizado_por` bigint(20) unsigned DEFAULT NULL,
  `anulada_por` bigint(20) unsigned DEFAULT NULL,
  `anulada_en` timestamp NULL DEFAULT NULL,
  `motivo_anulacion` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ventas_pdv_numero_venta_unique` (`numero_venta`),
  KEY `ventas_pdv_ubicacion_id_foreign` (`ubicacion_id`),
  KEY `ventas_pdv_cliente_id_foreign` (`cliente_id`),
  KEY `ventas_pdv_usuario_id_foreign` (`usuario_id`),
  KEY `ventas_pdv_anulada_por_foreign` (`anulada_por`),
  KEY `ventas_pdv_sesion_caja_id_foreign` (`sesion_caja_id`),
